#include <iostream>
#include <vector>
#include <numeric>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> next(n);
    for (int &x : next) {
        cin >> x;
        --x;
    }

    long long answer = 1;

    for (int start = 0; start < n; ++start) {
        int current = next[start];
        int length = 1;

        while (current != start && length <= n) {
            current = next[current];
            ++length;
        }

        if (current != start) {
            cout << -1 << '\n';
            return 0;
        }

        if (length % 2 == 0)
            length /= 2;

        answer = answer / gcd(answer, static_cast<long long>(length)) * length;
    }

    cout << answer << '\n';
    return 0;
}

