using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> a(n), indegree(n, 0);
    for (int &x : a) {
        cin >> x;
        --x;
        if (x < 0 || x >= n) {
            cout << -1 << '\n';
            return 0;
        }
        ++indegree[x];
    }

    for (int degree : indegree) {
        if (degree != 1) {
            cout << -1 << '\n';
            return 0;
        }
    }

    vector<bool> visited(n, false);
    long long answer = 1;

    for (int i = 0; i < n; ++i) {
        if (visited[i]) continue;

        int current = i;
        long long length = 0;

        do {
            visited[current] = true;
            current = a[current];
            ++length;
        } while (current != i);

        if (length % 2 == 0) length /= 2;
        answer = std::lcm(answer, length);
    }

    cout << answer << '\n';
    return 0;
}

